// ko message catalog, typed `Partial<Record<MessageId, string>>`:
// an id it lacks renders the English until it is translated (backfilled in
// batches; docs/frontend/i18n/README.md), and an id en no longer has is a
// compile error.
//
// Terms and style: docs/frontend/i18n/ja-ko.md. Sentences use 해요체;
// product nouns are Korean (에이전트, 컴퓨터, 서버); brand forms (Raft,
// Raft Computer, Raft Desktop, …) stay Latin. Korean has no count-plural
// distinction, so plural ICU uses a single `other` arm.

