  "agent.runtimeError.toolArgsInvalid": "모델이 잘못된 형식의 도구 호출 인수를 생성해서 Codex가 도구 호출을 거부했어요. 다른 모델을 사용해 보세요.",
  "agent.runtimeError.billingExhausted": "모델 서비스 잔액이 부족해요",
  "agent.runtimeError.billingExhaustedBody": "{agent}이(가) 지금은 답할 수 없어요. 이 에이전트가 사용하는 모델 서비스의 잔액과 결제 상태를 확인한 뒤 다시 시작하세요.",
  "agent.modelLimits.defaultsWarningTitle": "이 모델은 Raft 기본 한도를 사용 중일 수 있어요",
  "agent.modelLimits.defaultsWarningBody": "Computer가 보고한 바에 따르면 이 모델의 한도 중 하나 이상을 일치하는 카탈로그 항목에서 가져올 수 없어 Raft가 기본값으로 채웠어요. 현재 세션이 실제로 사용하는 한도는 아직 Raft가 확인할 수 없어요. 제공자의 실제 한도를 확인하세요. 이 알림 자체는 에이전트 실행을 막지 않아요. 직접 설정하려면 이 Agent의 설정을 열고 컨텍스트 창과 최대 출력 토큰을 입력하세요.",
  "agent.runtimeError.billingExhaustedViewModelSettings": "모델 설정 보기",
  "agent.runtimeError.billingExhaustedAskAdmin": "서버 관리자에게 해결을 요청하세요.",
  "agent.runtimeError.code.usageLimit.title": "사용 한도에 도달했어요",
  "agent.runtimeError.code.usageLimit.member": "에이전트가 사용하는 모델 제공업체의 사용 한도에 도달했어요. 한도가 초기화될 때까지 기다리거나, 에이전트 소유자에게 다른 모델이나 계정으로 바꿔 달라고 요청해 주세요.",
  "agent.runtimeError.code.usageLimit.manager": "모델 제공업체의 사용 한도에 도달했어요. 한도가 초기화될 때까지 기다리거나, 에이전트 설정에서 다른 모델이나 계정으로 바꿔 주세요.",
  "agent.runtimeError.code.billing.title": "제공업체 잔액이 소진됐어요",
  "agent.runtimeError.code.billing.member": "에이전트가 사용하는 모델 제공업체의 결제 잔액이나 크레딧이 소진됐어요. 에이전트 소유자에게 크레딧을 충전하거나 다른 모델 또는 제공업체로 바꿔 달라고 요청해 주세요.",
  "agent.runtimeError.code.billing.manager": "모델 제공업체의 결제 잔액이나 크레딧이 소진됐어요. 제공업체에서 크레딧을 충전하거나, 에이전트 설정에서 다른 모델 또는 제공업체로 바꿔 주세요.",
  "agent.runtimeError.code.modelUnavailable.title": "모델을 사용할 수 없어요",
  "agent.runtimeError.code.modelUnavailable.member": "에이전트에 설정된 모델을 해당 제공업체 계정에서 사용할 수 없어요. 에이전트 소유자에게 다른 모델을 선택하거나 플랜을 변경해 달라고 요청해 주세요.",
  "agent.runtimeError.code.modelUnavailable.manager": "에이전트의 모델을 해당 제공업체 계정에서 사용할 수 없어요. 에이전트 설정에서 다른 모델을 선택하거나 플랜을 변경해 주세요.",
  "agent.runtimeError.code.authRequired.title": "로그인이 필요해요",
  "agent.runtimeError.code.authRequired.member": "에이전트의 런타임에 로그인되어 있지 않거나 제공업체 자격 증명이 거부됐어요. 에이전트 소유자에게 다시 로그인하거나 자격 증명을 업데이트해 달라고 요청해 주세요.",
  "agent.runtimeError.code.authRequired.manager": "에이전트의 런타임에 로그인되어 있지 않거나 제공업체 자격 증명이 거부됐어요. 에이전트가 실행되는 컴퓨터에서 다시 로그인하거나 자격 증명을 업데이트해 주세요.",
  "agent.runtimeError.code.networkTimeout.title": "제공업체에 연결할 수 없어요",
  "agent.runtimeError.code.networkTimeout.member": "에이전트가 모델 제공업체에 연결하지 못했거나 요청 시간이 초과됐어요. 나중에 다시 시도해 주세요. 계속 이런 문제가 생기면 에이전트 소유자에게 컴퓨터의 네트워크를 확인해 달라고 요청해 주세요.",
  "agent.runtimeError.code.networkTimeout.manager": "에이전트가 모델 제공업체에 연결하지 못했거나 요청 시간이 초과됐어요. 나중에 다시 시도해 주세요. 계속 이런 문제가 생기면 에이전트가 실행되는 컴퓨터의 네트워크를 확인해 주세요.",
  "agent.runtimeError.code.inputTooLarge.title": "입력이 너무 커요",
  "agent.runtimeError.code.inputTooLarge.member": "에이전트의 입력이 모델이 받을 수 있는 크기보다 커요. 에이전트 소유자에게 세션을 초기화하거나 시작 컨텍스트를 줄여 달라고 요청해 주세요.",
  "agent.runtimeError.code.inputTooLarge.manager": "에이전트의 입력이 모델이 받을 수 있는 크기보다 커요. 세션을 초기화하거나 시작 컨텍스트를 줄여 주세요.",
  "agent.runtimeError.code.messageTooLarge.title": "메시지가 너무 길어요",
  "agent.runtimeError.code.messageTooLarge.member": "에이전트에게 보낸 메시지가 너무 길어 런타임이 한 번에 받을 수 없어서 전달되지 않았어요. 메시지를 줄이거나 여러 개로 나눠 주세요.",
  "agent.runtimeError.code.messageTooLarge.manager": "메시지가 너무 길어 이 에이전트의 런타임이 한 번에 받을 수 없어서 전달되지 않았어요. 메시지를 줄이거나 여러 개로 나눠 다시 보내 주세요.",
