  "machine.detail.upgradeFailureHint.unsafeKillModeGeneric": "이 Computer는 직접 만든 systemd 유닛 아래에서 실행되며, 이 버전에서는 그 KillMode 때문에 웹 업그레이드가 중단돼요. 해당 컴퓨터에서 유닛을 중지하고, 아래 설치 명령을 한 번 실행한 다음, 유닛을 다시 시작하세요.",
  "machine.detail.upgradeFailureHint.installationHeld": "이 Computer가 systemd 유닛 {unit} 안에서 실행되는 동안에는 설치 프로그램이 업그레이드할 수 없어요. 해당 컴퓨터에서 유닛을 중지하고({stopCommand}), 아래 설치 명령을 한 번 실행한 다음, 다시 시작하세요({startCommand}).",
  "machine.detail.upgradeFailureHint.installationHeldGeneric": "이 Computer가 systemd 유닛 안에서 실행되는 동안에는 설치 프로그램이 업그레이드할 수 없어요. 유닛을 중지하고, 아래 설치 명령을 한 번 실행한 다음, 다시 시작하세요.",
