  "settings.slackBridge.mentionSyncTitle": "일부 멤버를 아직 Slack의 @ 메뉴에서 선택할 수 없어요",
  "settings.slackBridge.mentionSyncRestricted": "메시지는 정상적으로 동기화돼요. 채널에 같은 이름을 가진 사람이 없다면 Slack에서 Raft 멤버의 @이름을 직접 입력해도 멘션이 전달돼요. Slack의 @ 메뉴에도 표시되게 하려면 Slack 관리자가 멤버의 사용자 그룹 생성을 허용해야 해요: 워크스페이스 설정 → 권한 → 사용자 그룹.",
  "settings.slackBridge.mentionSyncMissingScope": "메시지는 정상적으로 동기화돼요. 채널에 같은 이름을 가진 사람이 없다면 Slack에서 Raft 멤버의 @이름을 직접 입력해도 멘션이 전달돼요. Slack의 @ 메뉴에도 표시되게 하려면 Raft에 Slack 권한이 하나 더 필요해요. 아래의 ‘Slack 승인 갱신’을 사용하세요.",
  "settings.slackBridge.mentionSyncNameTaken": "메시지는 정상적으로 동기화돼요. 채널에 같은 이름을 가진 사람이 없다면 Slack에서 Raft 멤버의 @이름을 직접 입력해도 멘션이 전달돼요. Raft가 시도한 이름이 모두 Slack에서 이미 사용 중이라 멤버 {count, plural, other {#명}}이 Slack의 @ 메뉴에 등록되지 못했어요. Raft에서 이름을 바꾸거나 Slack에서 해당 이름을 비우면 해결돼요.",
  "settings.slackBridge.mentionSyncGeneric": "메시지는 정상적으로 동기화돼요. 채널에 같은 이름을 가진 사람이 없다면 Slack에서 Raft 멤버의 @이름을 직접 입력해도 멘션이 전달돼요. Slack이 일부 멤버의 @ 메뉴 등록을 거부했어요 ({code}). Raft가 계속 다시 시도하고 있어요.",
