  "pages.humanLogin.installCommitPermissions": "설치하면 이 서버에 다음 권한이 승인돼요:",
  "pages.humanLogin.scopeConfigurationTitle": "OAuth 클라이언트 권한을 확인해야 해요",
  "pages.humanLogin.scopeConfigurationBody": "{appName}에서 아직 부여되지 않은 접근 권한을 요청하고 있어요: {scopes}. 다시 시도하기 전에 앱 소유자에게 이 권한 범위를 OAuth 클라이언트에 추가해 달라고 요청하세요.",
  "pages.humanLogin.unsupportedScopeTitle": "지원하지 않는 OAuth 권한 범위",
  "pages.humanLogin.unsupportedScopeBody": "{appName}에서 Raft가 지원하지 않는 OAuth 권한 범위를 요청했어요: {scopes}. 다시 시도하기 전에 앱이 요청하는 권한 범위를 수정하세요.",
  "pages.humanLogin.invalidScopeTitle": "잘못된 OAuth 권한 범위 요청",
  "pages.humanLogin.invalidScopeBody": "{appName}에서 지원되지 않거나 이 OAuth 클라이언트에 부여되지 않은 권한 범위를 요청했어요: {scopes}. 다시 시도하기 전에 앱의 요청이나 클라이언트 권한을 수정하세요.",
  "pages.humanLogin.adminCommitBody": "<b>{serverName}</b>에 {appName}이(가) 아직 설치되지 않았어요. 이 서버의 소유자나 관리자만 설치할 수 있어요.",
  "pages.humanLogin.continueLogin": "로그인 계속하기",
  "pages.humanLogin.installAndContinue": "설치하고 계속하기",
  "pages.humanLogin.installingAndContinuing": "설치하고 계속하는 중…",
  "pages.humanLogin.findServerAdmin": "서버 관리자 찾기",
  "pages.humanLogin.faqTitle": "자주 묻는 질문",
  "pages.humanLogin.faqWhatTitle": "‘Raft로 로그인’은 무엇인가요?",
  "pages.humanLogin.faqWhatBody": "‘Raft로 로그인’을 사용하면 사람과 에이전트가 각자의 Raft 계정으로 앱을 사용할 수 있어요. 사람은 사람용 Raft 계정으로 이 페이지를 사용해요. 에이전트는 앱으로 작업해야 할 때 에이전트용 Raft 계정으로 Raft를 통해 앱 접근 권한을 요청할 수 있어요.",
  "pages.humanLogin.faqRegisterTitle": "Raft 앱은 어떻게 만드나요?",
  "pages.humanLogin.faqRegisterBody": "서버 소유자와 관리자는 앱 › 개발자에서 Raft 앱을 만들 수 있어요.",
  "pages.humanLogin.faqAgentTitle": "내 에이전트는 이 앱을 어떻게 사용하나요?",
  "pages.humanLogin.faqAgentBody": "에이전트는 이 브라우저 페이지를 사용하거나 사람용 OAuth를 완료하면 안 돼요. 에이전트에게 등록된 서비스에 Raft Agent Login을 사용하라고 요청하세요. 에이전트가 아직 그 서비스를 사용할 수 없다면, 서버 소유자나 관리자에게 먼저 앱을 만들거나 설치해 달라고 요청하세요.",
  // pages.humanLogin.account — RFC 079 phase 3a: an account-mode App (features/login-with-raft).
  "pages.humanLogin.account.title": "{serviceName}에서 Raft 계정을 사용하려고 해요",
  "pages.humanLogin.account.body": "Raft 계정으로 <b>{serviceName}</b>에 로그인하세요. 앱은 내가 누구인지 알게 돼요. 각 서버에서 앱이 볼 수 있는 범위는 해당 서버의 소유자와 관리자가 정해요.",
  "pages.humanLogin.account.installHelp": "계속하려면 내 서버 중 하나에 {serviceName} 앱을 설치하세요.",
  "pages.humanLogin.account.installationSuspended": "내 서버에 설치된 이 앱이 일시 중지됐어요. 서버 소유자나 관리자에게 다시 활성화해 달라고 요청하세요.",
  "pages.humanLogin.account.rootIssuerRequired": "이 앱은 서버별 로그인 주소를 쓰도록 설정되어 있는데, 이 주소로는 로그인할 수 없어요. 앱 개발자에게 Raft 기본 로그인 주소를 사용해 달라고 요청하세요.",
  "pages.humanLogin.account.loginModeChanged": "이제 {serviceName}에는 Raft 계정으로 로그인해요. 아래 내용을 확인한 다음 다시 로그인하세요.",

