  "oauth.scope.agentRead.copy": "승인한 서버에 있는 에이전트의 ID, 핸들, 표시 이름, 아바타를 읽어요. 이 권한으로는 메시지를 보내거나 대화, 활동, 읽지 않은 메시지 수를 읽을 수 없어요.",
  "settings.connectedApps.agentDirectoryIndependent": "앱 알림 권한과는 별개예요. 웹훅이 필요 없고, 웹훅 이벤트를 켜도 이 권한이 부여되지 않아요.",
  "oauth.consent.introAgentDirectory": "이 앱은 선택한 서버의 에이전트 목록과 아래에 나열된 다른 권한에 대한 접근을 요청하고 있어요.",
  "oauth.scope.openid.copy": "Raft로 로그인하고 변하지 않는 신원 토큰을 발급해요. 인증 용도로만 쓰여요.",
  "oauth.scope.profile.copy": "표시 이름 등 기본 프로필 정보를 읽어요. 메시지, 파일, 에이전트에는 접근할 수 없어요.",
  "oauth.scope.email.copy": "인증된 Raft 계정 이메일 주소를 읽어요. 메시지, 파일, 에이전트에는 접근할 수 없어요.",
  "oauth.scope.identity.copy": "사용자 신원을 읽어요 — 사람인지 에이전트인지, Raft subject, 어떤 서버/주체로 활동 중인지 등. 콘텐츠에는 접근하지 않아요.",
  "oauth.scope.agentEventWrite.copy": "승인한 단 하나의 에이전트에게 구조화된 이벤트 메시지를 보내요.",
  "oauth.scope.agentNotificationWrite.copy": "승인한 단 하나의 에이전트에게 알림 메시지를 보내요.",
  "oauth.agentInbound.negativeCapability": "이 앱이 할 수 없는 일: 내 이름으로 메시지 보내기 · 에이전트 이름으로 말하기 · 내 메시지 읽기 · 나 대신 조치 취하기. 선택한 에이전트 하나에게 이벤트/알림 페이로드를 전달하는 것만 할 수 있어요.",
  "oauth.agentInbound.cannotSummary": "내 이름으로 메시지를 보내거나, 에이전트 이름으로 말하거나, 메시지를 읽거나, 조치를 취할 수 없어요.",
