  "oauth.consent.introAgentMessaging": "인식된 기능은 아래와 같아요. 에이전트 메시징에는 Agent Login이 필요해요.",
  "oauth.consent.introUnrecognized": "인식된 기능은 아래와 같아요. 계속하기 전에 인식되지 않은 요청 권한 범위를 검토해 주세요.",
