  // Add seats in place (AddSeatsDialog, task #10 #proj-commercial).
  "addSeats.askIntro": "소유자에게 카드를 보내 {kind, select, join {시트} other {시트}} 추가 승인을 요청하세요. {kind, select, agent {시트가 추가되면 소유자가 {name} 에이전트를 만들 수 있는 카드를 보내 줄 수 있어요.} assistant {시트가 추가되면 알림을 받고 어시스턴트를 만들 수 있어요.} invite {시트가 추가되면 소유자가 초대를 보내요.} join {시트가 추가되면 {name} 님이 링크를 다시 열어 참여할 수 있어요.} other {시트가 추가되면 소유자가 {name} 님을 {role, select, admin {관리자로} other {멤버로}} 전환해요.}}",
