  "upgradeDialog.externalLimit.ask": "{server} 서버는 무료 요금제의 외부 채널 1개를 이미 쓰고 있어요. 외부 사람과 채널을 더 공유할 수 있도록 {server} 서버를 Pro로 업그레이드할 수 있을까요?",
  "upgradeDialog.externalLimit.askChannel": "{server} 서버의 무료 요금제 외부 채널 1개는 {channel} 채널이에요. 외부 사람과 채널을 더 공유할 수 있도록 {server} 서버를 Pro로 업그레이드할 수 있을까요?",
